-- Project schedule. These are calendar dates ('YYYY-MM-DD', the user's local
-- day), not instants, so they are not converted to UTC like timestamps.
ALTER TABLE projects ADD COLUMN start_date TEXT;
ALTER TABLE projects ADD COLUMN end_date TEXT;  -- optional deadline

-- 1 = generated by "Tạo dữ liệu mẫu"; removable in one go.
ALTER TABLE projects ADD COLUMN sample INTEGER NOT NULL DEFAULT 0;

-- Existing projects start on their first tracked day, else their creation day.
UPDATE projects
SET start_date = COALESCE(
    (SELECT date(MIN(started_at), 'localtime') FROM sessions WHERE sessions.project_id = projects.id),
    date(created_at, 'localtime')
);
